module Top;
    int i_header = 12, i_len = 5, i_crc = 42;
    byte i_data[];
    int o_header, o_len, o_crc;
    byte o_data[];
    byte pkt[$];
    initial begin
        i_data = new[5];
        foreach (i_data[k]) i_data[k] = byte'(k + 1);
        pkt = {<< 8 {i_header, i_len, i_data, i_crc}};
        $display("pkt size=%0d pkt[0]=%0d pkt[4]=%0d pkt[13]=%0d", pkt.size(), pkt[0], pkt[4], pkt[13]);
        {<< 8 {o_header, o_len, o_data, o_crc}} = pkt;
        $display("header=%0d len=%0d crc=%0d size=%0d data[0]=%0d data[4]=%0d", o_header, o_len, o_crc, o_data.size(), o_data[0], o_data[4]);
    end
endmodule
